from datetime import datetime
import re
import json

output_items = []

# --- Helper Functions ---

def is_valid_timestamp(value):
    try:
        if isinstance(value, (int, float)):
            return False
        datetime.fromisoformat(str(value).replace('Z', '+00:00'))
        return True
    except ValueError:
        try:
            datetime.strptime(str(value), "%Y-%m-%dT%H:%M:%S.%fZ")
            return True
        except ValueError:
            return False

def get_currency_symbol(value):
    if not isinstance(value, str):
        return None
    currency_symbols = ['₹', '$', '€', '£', '¥', '₩', '฿', 'zł', 'kr', 'R$', 'C$', 'A$']
    cleaned_val = value.strip()
    for symbol in currency_symbols:
        if cleaned_val.startswith(symbol):
            return symbol
    return None

def normalize_currency_value(value, currency_symbol):
    if not isinstance(value, str) or not currency_symbol:
        return value
    try:
        numeric_part = value.replace(currency_symbol, '').replace(',', '')
        return float(numeric_part)
    except ValueError:
        return None

def normalize_percentage_value(value):
    if not isinstance(value, str):
        return value
    if not value.strip().endswith('%'):
        return value
    try:
        numeric_part = value.replace('%', '')
        return float(numeric_part) / 100.0
    except ValueError:
        return None

def parse_date_string(value):
    if isinstance(value, str) and re.match(r'^\d{2}/\d{2}/\d{4}$', value):
        try:
            date_obj = datetime.strptime(value, "%m/%d/%Y")
            return date_obj.isoformat() + "Z"
        except ValueError:
            return None
    return value


# --- Main Logic Loop ---

for item in _items:
    # Unpack the legacy 'json' wrapper safely
    internal_data = item.get('json', item)

    sheet_name = internal_data.get('sheet_name', 'default')

    # FIX 1: Safely parse column_mapping if it arrived as a string
    raw_mapping = internal_data.get('column_mapping') or {}
    if isinstance(raw_mapping, str):
        try:
            column_mapping = json.loads(raw_mapping)
        except Exception:
            column_mapping = {}
    else:
        column_mapping = raw_mapping

    # FIX 2: Safely parse rows_data if it arrived as a string
    raw_rows = internal_data.get('rows_data') or []
    if isinstance(raw_rows, str):
        try:
            rows = json.loads(raw_rows)
        except Exception:
            rows = []
    else:
        rows = raw_rows

    table_name = f"ai_table_{sheet_name}"

    all_columns = []
    seen_columns = set()

    for row in rows:
        # Handle cases where rows are double-nested in a 'json' key
        row_json = row.get('json', row) if isinstance(row, dict) else row

        # FIX 3: Ensure row_json is a real dictionary before parsing keys
        if isinstance(row_json, str):
            try:
                row_json = json.loads(row_json)
            except Exception:
                row_json = {}

        if isinstance(row_json, dict):
            for col in row_json.keys():
                if col not in seen_columns:
                    seen_columns.add(col)
                    all_columns.append(col)

    mapped_columns = []
    for col in all_columns:
        if isinstance(column_mapping, dict) and col in column_mapping and isinstance(column_mapping[col], dict) and 'newName' in column_mapping[col]:
            mapped_columns.append(column_mapping[col]['newName'])
        else:
            mapped_columns.append(col)

    formatted_rows = []
    for row in rows:
        row_json = row.get('json', row) if isinstance(row, dict) else row
        if isinstance(row_json, str):
            try:
                row_json = json.loads(row_json)
            except Exception:
                row_json = {}

        formatted_row = {}

        for index, col in enumerate(all_columns):
            mapped_col = mapped_columns[index]
            value = row_json.get(col) if isinstance(row_json, dict) else None

            col_map_info = column_mapping.get(col, {}) if isinstance(column_mapping, dict) else {}
            type_info = col_map_info.get('typeInfo', {'type': 'TEXT'}) if isinstance(col_map_info, dict) else {'type': 'TEXT'}

            if value == "" or value is None:
                value = None
            elif type_info.get('isCurrency'):
                symbol = get_currency_symbol(value)
                value = normalize_currency_value(value, symbol) if symbol else None
            elif type_info.get('isPercentage'):
                if isinstance(value, str) and value.strip().endswith('%'):
                    value = normalize_percentage_value(value)
                else:
                    try:
                        value = float(value) / 100.0
                    except (ValueError, TypeError):
                        value = None
            elif type_info.get('type') in ["DECIMAL(15,2)", "INTEGER"]:
                if isinstance(value, str):
                    try:
                        value = float(value.replace(',', ''))
                    except ValueError:
                        value = None
                elif isinstance(value, (int, float)):
                    value = float(value)
                else:
                    value = None
            elif type_info.get('type') == "BOOLEAN":
                if isinstance(value, str):
                    lowercased = value.strip().lower()
                    if lowercased == "true":
                        value = True
                    elif lowercased == "false":
                        value = False
                    else:
                        value = None
                else:
                    value = bool(value)
            elif type_info.get('type') == "TIMESTAMP":
                if isinstance(value, str) and re.match(r'^\d{2}/\d{2}/\d{4}$', value):
                    value = parse_date_string(value)
                elif is_valid_timestamp(value):
                    try:
                        value = str(value).replace('Z', '')
                        value = datetime.fromisoformat(value).isoformat() + "Z"
                    except ValueError:
                        value = None
                else:
                    value = None
            elif type_info.get('type') == "TEXT":
                value = str(value) if value is not None else None

            formatted_row[mapped_col] = value
        formatted_rows.append(formatted_row)

    if not formatted_rows or not mapped_columns:
        output_items.append({'json': {'query': '', 'parameters': []}})
        continue

    value_placeholders_list = []
    placeholder_counter = 1

    for row_idx in range(len(formatted_rows)):
        row_placeholders = []
        for col_idx in range(len(mapped_columns)):
            row_placeholders.append(f"${placeholder_counter}")
            placeholder_counter += 1
        value_placeholders_list.append(f"({', '.join(row_placeholders)})")

    value_placeholders = ", ".join(value_placeholders_list)

    escaped_cols = [f'"{col}"' for col in mapped_columns]
    insert_query = f"INSERT INTO {table_name} ({', '.join(escaped_cols)}) VALUES {value_placeholders};"

    parameters = []
    for row in formatted_rows:
        for col in mapped_columns:
            parameters.append(row.get(col))

    output_items.append({
        'json': {
            'query': insert_query,
            'parameters': parameters
        }
    })

return output_items

